        entries.put("Aufnahme folgt dem Gateway und seinen bestätigten Funktionen. Darstellungs-Freeze stoppt die Aufnahme nicht.", new String[] { "Aufnahme folgt dem Gateway und seinen bestätigten Funktionen. Darstellungs-Freeze stoppt die Aufnahme nicht.", "Acquisition follows the gateway and its declared capabilities. Display freeze does not stop acquisition.", "Verkryging volg die poort en sy verklaarde funksies. Vertoningsvries stop nie verkryging nie." });
        entries.put("Acquisition follows the gateway and its declared capabilities. Display freeze does not stop acquisition.", new String[] { "Aufnahme folgt dem Gateway und seinen bestätigten Funktionen. Darstellungs-Freeze stoppt die Aufnahme nicht.", "Acquisition follows the gateway and its declared capabilities. Display freeze does not stop acquisition.", "Verkryging volg die poort en sy verklaarde funksies. Vertoningsvries stop nie verkryging nie." });
        entries.put("AUFNAHME FOLGT DEM GATEWAY UND SEINEN BESTÄTIGTEN FUNKTIONEN. DARSTELLUNGS-FREEZE STOPPT DIE AUFNAHME NICHT.", new String[] { "AUFNAHME FOLGT DEM GATEWAY UND SEINEN BESTÄTIGTEN FUNKTIONEN. DARSTELLUNGS-FREEZE STOPPT DIE AUFNAHME NICHT.", "ACQUISITION FOLLOWS THE GATEWAY AND ITS DECLARED CAPABILITIES. DISPLAY FREEZE DOES NOT STOP ACQUISITION.", "VERKRYGING VOLG DIE POORT EN SY VERKLAARDE FUNKSIES. VERTONINGSVRIES STOP NIE VERKRYGING NIE." });
